import sys, os, io
input = sys.stdin.readline

def is_valid(x, y):
	if min(x, y) >= 0 and x < n and (y < m) and ((x, y) not in vis) and (a[x][y] != '#'):
		return 1
for _ in range(int(input())):
	(n, m) = [int(i) for i in input().split()]
	a = []
	for i in range(n):
		a.append(list(input().strip()))
	vis = set()
	dx = [1, -1, 0, 0]
	dy = [0, 0, 1, -1]
	ans = 0
	depth = 0
	stack = [(0, 0)]
	while len(vis) < n * m:
		while stack:
			(x, y) = stack.pop()
			vis.add((x, y))
			depth = max(depth, x)
			for k in range(4):
				(nx, ny) = (x + dx[k], y + dy[k])
				if is_valid(nx, ny):
					vis.add((nx, ny))
					stack.append((nx, ny))
		if depth != n - 1:
			ans += 1
			for i in range(m):
				a[depth + 1][i] == '.'
				stack.append((depth + 1, i))
		elif (n - 1, m - 1) not in vis:
			ans += 1
			break
		else:
			break
	print(ans)
